from soar.intel.indicators import defang, detect_type, extract_from_text, normalise_value, refang
from soar.intel.mitre import parse_technique
from soar.intel.scoring import aggregate_score, verdict_for_score

if key == "ioc.extract":
    found = extract_from_text(inputs["text"])
    return {"indicators": found, "count": len(found)}
if key == "ioc.detect_type":
    return {"type": detect_type(inputs["value"])}
if key == "ioc.normalise":
    kind = detect_type(inputs["value"])
    return {"type": kind, "normalised": normalise_value(kind, inputs["value"])}
if key == "ioc.defang":
    return {"defanged": defang(inputs["value"])}
if key == "ioc.refang":
    return {"refanged": refang(inputs["value"])}
if key == "intel.score":
    verdicts = inputs["verdicts"]
    score = aggregate_score(verdicts)
    return {"score": score, "verdict": verdict_for_score(score, len(verdicts))}
if key == "mitre.parse":
    return parse_technique(inputs["raw"])
raise KeyError("no built-in handler for %r" % key)
